import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, color, mix, smoothstep, oneMinus, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, DirectionalLight, Box3 } = ctx.THREE;

  const COLORS = (config.intent && config.intent.visualSpec && config.intent.visualSpec.colors) || {};
  const BG = COLORS.background || '#0b0b10';
  const SURFACE = COLORS.surface || '#111117';
  const PAPER = COLORS.paper || '#e8ecf2';
  const ACCENT = COLORS.accent || '#ff2a38';
  const HAIRLINE = '#23232b';

  const root = new Group();
  root.name = 'data-ticker-ribbon';

  const disposables = [];
  const primitiveHandles = [];
  let loopTween = null;

  // ---------------------------------------------------------------
  // STAGE BACKDROP — 7x6 at z=-2.5, subtle vertical gradient (spec colors only)
  // ---------------------------------------------------------------
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = mix(
    color(BG),
    color(SURFACE),
    smoothstep(float(0.0), float(1.0), uv().y).mul(0.55)
  );
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---------------------------------------------------------------
  // NODE-LOCAL RIM LIGHT (scene provides ambient 0.6 + key 1.2)
  // ---------------------------------------------------------------
  const rim = new DirectionalLight(PAPER, 0.7);
  rim.position.set(-2.0, 1.6, -1.5);
  root.add(rim);

  // ---------------------------------------------------------------
  // RAIL PLANE — 7.0 x 0.35, albedo #111117, roughness 0.6, metalness 0.2
  // ---------------------------------------------------------------
  const railGeo = new PlaneGeometry(7.0, 0.35);
  const railMat = new MeshStandardNodeMaterial({
    color: SURFACE,
    roughness: 0.6,
    metalness: 0.2
  });
  const rail = new Mesh(railGeo, railMat);
  rail.position.set(0, 0, 0);
  root.add(rail);
  disposables.push(railGeo, railMat);

  // Hairlines top + bottom, 0.006 units, #23232b
  const hairGeo = new PlaneGeometry(7.0, 0.006);
  const hairMat = new MeshBasicNodeMaterial({ color: HAIRLINE });
  const hairTop = new Mesh(hairGeo, hairMat);
  hairTop.position.set(0, 0.172, 0.005);
  const hairBot = new Mesh(hairGeo, hairMat);
  hairBot.position.set(0, -0.172, 0.005);
  root.add(hairTop, hairBot);
  disposables.push(hairGeo, hairMat);

  // ---------------------------------------------------------------
  // TICKER CONTENT
  // ---------------------------------------------------------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const figures = items.length
    ? items.map((it) => String(it.text))
    : ['CAL NA-01 BEAT 28800 VPH'];

  const TEXT_TARGET_H = 0.12;   // scene-unit cap height for mono figures
  const GAP = 0.5;              // 2x base unit each side of every tick
  const TICK_W = 0.02;
  const TICK_H = 0.14;

  const tickGeo = new PlaneGeometry(TICK_W, TICK_H);
  const tickMat = new MeshStandardNodeMaterial({
    color: ACCENT,
    emissive: ACCENT,
    emissiveIntensity: 1.5,
    roughness: 0.5,
    metalness: 0.0
  });
  disposables.push(tickGeo, tickMat);

  const measureBox = new Box3();

  // Builds one full strip copy; returns { group, width }
  function buildStrip() {
    const strip = new Group();
    let cursor = 0;
    for (let i = 0; i < figures.length; i++) {
      const txt = ctx.fontAtlas.createText(figures[i], {
        fontSize: 13,
        color: PAPER,
        align: 'left',
        letterSpacingPx: 0.78
      });
      measureBox.setFromObject(txt);
      const rawW = Math.max(measureBox.max.x - measureBox.min.x, 0.0001);
      const rawH = Math.max(measureBox.max.y - measureBox.min.y, 0.0001);
      const s = TEXT_TARGET_H / rawH;
      txt.scale.setScalar(s);
      txt.position.x = cursor - measureBox.min.x * s;
      txt.position.y = -((measureBox.min.y + measureBox.max.y) * 0.5) * s;
      strip.add(txt);
      cursor += rawW * s;

      // gap + accent tick + gap (never punctuation glyphs)
      cursor += GAP;
      const tick = new Mesh(tickGeo, tickMat);
      tick.position.set(cursor + TICK_W * 0.5, 0, 0);
      strip.add(tick);
      cursor += TICK_W + GAP;
    }
    return { group: strip, width: cursor };
  }

  // Three identical copies at -W, 0, +W for a zero-seam loop across the window
  const stripContainer = new Group();
  stripContainer.position.set(0, 0, 0.02); // figures float above the rail for a crisp key-lit edge
  root.add(stripContainer);

  const first = buildStrip();
  const stripWidth = first.width;
  first.group.position.x = 0;
  stripContainer.add(first.group);

  const before = buildStrip();
  before.group.position.x = -stripWidth;
  stripContainer.add(before.group);

  const after = buildStrip();
  after.group.position.x = stripWidth;
  stripContainer.add(after.group);

  // Constant velocity 0.4 units/s leftward, linear timing, period = W / 0.4
  loopTween = gsap.to(stripContainer.position, {
    x: -stripWidth,
    duration: stripWidth / 0.4,
    ease: 'none',
    repeat: -1
  });

  // ---------------------------------------------------------------
  // EDGE FADE MASKS — opaque block + 0.6-unit ramp dissolving into the stage
  // ---------------------------------------------------------------
  const fadeGeo = new PlaneGeometry(2.6, 0.5);

  const fadeLeftMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  fadeLeftMat.colorNode = color(BG);
  fadeLeftMat.opacityNode = oneMinus(smoothstep(float(0.769), float(1.0), uv().x));
  const fadeLeft = new Mesh(fadeGeo, fadeLeftMat);
  fadeLeft.position.set(-4.2, 0, 0.06);
  fadeLeft.renderOrder = 10;
  root.add(fadeLeft);

  const fadeRightMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  fadeRightMat.colorNode = color(BG);
  fadeRightMat.opacityNode = smoothstep(float(0.0), float(0.231), uv().x);
  const fadeRight = new Mesh(fadeGeo, fadeRightMat);
  fadeRight.position.set(4.2, 0, 0.06);
  fadeRight.renderOrder = 10;
  root.add(fadeRight);

  disposables.push(fadeGeo, fadeLeftMat, fadeRightMat);

  // ---------------------------------------------------------------
  // CINEMATIC PRIMITIVES (applied via ctx.primitives, never inlined)
  // ---------------------------------------------------------------
  const prims = config.cinematicPrimitives ?? [];
  for (const p of prims) {
    const fn = ctx.primitives[p.name];
    if (fn) {
      const handle = fn(root, p.params || {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  // Weighted entrance: rise-in on the whole ribbon (never linear on hero motion)
  root.position.y -= 0.25;
  const entrance = gsap.to(root.position, {
    y: root.position.y + 0.25,
    duration: 0.7,
    ease: 'power3.out'
  });

  // ---------------------------------------------------------------
  // HANDLERS + CLEANUP
  // ---------------------------------------------------------------
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    if (loopTween) loopTween.kill();
    entrance.kill();
    for (const h of primitiveHandles) {
      if (h && typeof h.cleanup === 'function') h.cleanup();
    }
    root.traverse((obj) => {
      if (obj.geometry && typeof obj.geometry.dispose === 'function') obj.geometry.dispose();
      if (obj.material) {
        const mats = Array.isArray(obj.material) ? obj.material : [obj.material];
        for (const m of mats) {
          if (m && typeof m.dispose === 'function') m.dispose();
        }
      }
    });
    for (const d of disposables) {
      if (d && typeof d.dispose === 'function') d.dispose();
    }
  };

  return root;
}
